        bottom_half = [p for p in image_patch.find("image") if p.lower >= center_y]
        if len(top_half) > len(bottom_half):
            return top_half[0]
        elif len(top_half) < len(bottom_half):
            return bottom_half[0]
        else:
            return person_patch
    else:
        return None

